// ======================================================
// CALENDAR DATA STORAGE (GLOBAL STATE)
// ======================================================

// These objects are filled by JSON files generated by Apps Script.
// We do NOT hardcode anything here. We only store what the JSON gives us.

let availability = {};       // availability.json
let blocksByDay = {};        // blocks.json
let sunsetTimes = {};        // sunset.json
let complexMapFromJson = {}; // complexes.json (fieldId → complexName)

// Calendar state
let currentView = "week";
let currentDate = new Date();


// ======================================================
// JSON LOADING FUNCTIONS
// ======================================================

// Load availability.json
async function loadAvailability() {
  try {
    const res = await fetch("availability.json");
    availability = await res.json();
    console.log("Availability loaded:", Object.keys(availability));
  } catch (err) {
    console.error("Failed to load availability.json", err);
  }
}

// Load blocks.json
async function loadBlocks() {
  try {
    const res = await fetch("blocks.json");
    blocksByDay = await res.json();
    console.log("Blocks loaded:", Object.keys(blocksByDay));
  } catch (err) {
    console.error("Failed to load blocks.json", err);
  }
}

// Load sunset.json
async function loadSunsetTimes() {
  try {
    const res = await fetch("sunset.json");
    sunsetTimes = await res.json();
    console.log("Sunset times loaded:", Object.keys(sunsetTimes));
  } catch (err) {
    console.error("Failed to load sunset.json", err);
  }
}

// Load complexes.json (fieldId → complexName)
async function loadComplexMap() {
  try {
    const res = await fetch("complexes.json");
    complexMapFromJson = await res.json();
    console.log("Complex map loaded:", complexMapFromJson);
  } catch (err) {
    console.error("Failed to load complexes.json", err);
  }
}
